import{_ as e,o,c as i,a2 as s}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Inscripción","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/inscription.md","filePath":"es/guide/professions/inscription.md"}'),r={name:"es/guide/professions/inscription.md"};function n(t,a,c,l,d,p){return o(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="inscription" tabindex="-1">Inscripción <a class="header-anchor" href="#inscription" aria-label="Enlace permanente a &quot;Inscripción&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · No establecido como jugable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Registra, conserva y modifica con cuidado el conocimiento mágico.</li><li>Los pergaminos, las variantes y los grimorios organizados ofrecen funciones tácticas y económicas.</li><li>Comprar un pergamino de lanzamiento no compra conocimiento permanente; los productos físicos siguen expuestos al riesgo.</li></ul><p><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actividad</th><th>Qué haces</th></tr></thead><tbody><tr><td>Ejecutar el oficio</td><td>La <a href="/Syrolands-Public/es/guide/characters/skills.html">habilidad</a> de Inscripción permite ejecutar el trabajo; los métodos aprendidos determinan qué puede escribirse.</td></tr><tr><td>Especializarse</td><td>Los pergaminos de combate, la notación de variantes, la indexación y la encuadernación de grimorios son caminos posibles.</td></tr><tr><td>Preparar referencias útiles</td><td>La notación clara y los libros organizados pueden mejorar la consulta y la preparación.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Dirección de Syrolands</th></tr></thead><tbody><tr><td>Los escribas crean pergaminos de hechizos y libros; el oficio ya apoya a los magos.</td><td>Las variantes controladas, la notación y la conservación amplían el trabajo de conocimiento de la profesión.</td></tr><tr><td>Un hechizo escrito proporciona un recurso físico para lanzar magia.</td><td>Un pergamino preparado puede ofrecer una consulta de emergencia más rápida, con un coste consumible.</td></tr></tbody></table><p>La comparación usa los ciclos conocidos de los oficios de UO; las referencias oficiales también cubren expansiones posteriores. <a href="https://uo.com/wiki/ultima-online-wiki/skills/inscription/" target="_blank" rel="noreferrer">Inscription</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un escriba podría hacerse conocido por sus pergaminos de combate fiables o sus grimorios bien indexados. El cliente obtiene una referencia útil, no la posesión automática del conocimiento raro del escriba.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progresión y compromisos <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Enlace permanente a &quot;Progresión y compromisos&quot;">​</a></h2><ul><li>Las estructuras mágicas conocidas, Magery, los reactivos y Alquimia pueden apoyar la producción. La habilidad por sí sola no desbloquea todos los métodos.</li><li>Los permisos de copia y enseñanza, las protecciones y los rituales siguen abiertos. La calidad artesanal no concede protección frente al saqueo ni una bonificación plana de habilidad.</li></ul><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/magic/spellbooks-scrolls-and-reagents.html">Libros y materiales</a> · <a href="/Syrolands-Public/es/guide/magic/variants-and-glyphs.html">Variantes de hechizos</a> · <a href="/Syrolands-Public/es/guide/professions/alchemy.html">Alquimia</a> · <a href="/Syrolands-Public/es/guide/professions/overview.html">Sistema de profesiones</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/professions/inscription.html">Inscripción</a></p>',18)])])}const h=e(r,[["render",n]]);export{u as __pageData,h as default};
